#include <iostream>
#include <vector>
#include <string>

int main() {
    std::vector<int> openIndices;
    std::vector<int> closeIndices;
    int num;
    std::cin >> num;
    std::string strInput;
    std::cin >> strInput;

    for (int i = 0; i < num; i++) {
        if (strInput[i] == '(') {
            openIndices.push_back(i);
        } else if (strInput[i] == ')') {
            closeIndices.push_back(i);
        }
    }

    int wordCount = 0;
    auto extractSegments = [&](const std::string& s, const std::vector<int>& starts, const std::vector<int>& ends) {
        std::vector<std::string> segments;
        for (size_t i = 0; i < starts.size(); i++) {
            segments.push_back(s.substr(starts[i] + 1, ends[i] - starts[i] - 1));
        }
        return segments;
    };

    for (const auto& segment : extractSegments(strInput, openIndices, closeIndices)) {
        size_t start = 0;
        size_t end = 0;
        size_t pos = 0;
        while ((pos = segment.find('_', start)) != std::string::npos) {
            std::string part = segment.substr(start, pos - start);
            if (!part.empty()) {
                wordCount++;
            }
            start = pos + 1;
        }
        // last part after last underscore
        std::string lastPart = segment.substr(start);
        if (!lastPart.empty()) {
            wordCount++;
        }
    }

    int maxWordLen = 0;
    openIndices.push_back(strInput.length());
    closeIndices.insert(closeIndices.begin(), 0);
    size_t startIdx = (strInput[0] == '(') ? 1 : 0;

    for (size_t i = startIdx; i < closeIndices.size(); i++) {
        std::string segment;
        if (strInput[closeIndices[i]] == ')') {
            segment = strInput.substr(closeIndices[i] + 1, openIndices[i] - closeIndices[i] - 1);
        } else {
            segment = strInput.substr(closeIndices[i], openIndices[i] - closeIndices[i]);
        }
        size_t start = 0;
        size_t pos = 0;
        while ((pos = segment.find('_', start)) != std::string::npos) {
            std::string part = segment.substr(start, pos - start);
            if (part.length() > maxWordLen && part.find('(') == std::string::npos && part.find(')') == std::string::npos) {
                maxWordLen = part.length();
            }
            start = pos + 1;
        }
        // last part after last underscore
        std::string lastPart = segment.substr(start);
        if (lastPart.length() > maxWordLen && lastPart.find('(') == std::string::npos && lastPart.find(')') == std::string::npos) {
            maxWordLen = lastPart.length();
        }
    }

    std::cout << maxWordLen << " " << wordCount << std::endl;

    return 0;
}

